import React, { useState, useEffect, useRef } from 'react'
import { CircleUserRound } from 'lucide-react'
import SignedInDrop from './SignedInDrop'
import "./Header.scss"

const Header = () => {
  const dropdownRef = useRef()
  const [isOpen, setIsOpen] = useState(false)

  const [username, setUsername] = useState('Guest')

  const toggleDropdown = () => {
    setIsOpen(true) // profile click reveals or hides dropdown
  }

  useEffect(() => {
    const handleClickOut = (e) => {
      if (!dropdownRef.current.contains(e.target)) {
        isOpen(false)
      }
    }
    
    document.addEventListener("mousedown", handleClickOut)

      return () => {
        document.removeEventListener("mousedown", )
      }
    })

  return (
    <div className="header-container">
      <div className="header-section-container">
        <div className="profile-container">
          <CircleUserRound className="profile-icon" onClick={toggleDropdown} />
          {isOpen && (
            <SignedInDrop username={username} dropdownRef={dropdownRef} isOpen={isOpen} />
          )}
        </div>
      </div>
    </div>
  )
}

export default Header
